from __future__ import annotations

# BÀI SÁP NHẬP V2 - CHUẨN HÓA FILE PA SẮP XẾP THÀNH SỔ PHƯƠNG ÁN CHÍNH THỨC
# - Không sửa database.
# - Khóa endpoint XEM TRƯỚC / THỰC HIỆN SÁP NHẬP.
# - Hiển thị phương án chính thức theo đúng nhóm cột F của file Excel.
# - Điểm kiểm chứng: Cửa Lò - Tiểu học phải có đúng 4 nhóm.

import base64
import hashlib
import json
import os
