import re
import shutil
import sqlite3
import sys
import unicodedata
from datetime import datetime
from pathlib import Path

EXPECTED_CURRENT = {
    "app/routers/school_merger.py": "7d049837946df1c629d369ecfced72b85ecdb008079d34fcb9050b2d9468b7ab",
    "app/templates/data_tools/school_merger.html": "77c008a3bcf29f1ce7f295ed1a397e83b8d092acdeff6b874afec2faeec101b6",
    "app/templates/data_tools/school_merger_plans.html": "c801952fdcc4ab814c5e77800650ed3c7d349bebc336f8d740f4c35dad8bcd61"
}
NEW_HASHES = {
    "app/services/school_merger_official_registry.py": "8ce1f5f045737c57511a401d49a5fa264b8166b9f84c4063f0af26647505f656",
    "data/school_merger_official_registry.json": "f58969c363d9ec81739a9ee2be9d982b542e602c545f17fdc9c2ddcf397eca6a",
    "app/routers/school_merger.py": "1a92a8f91f5861ffdda74a8e3631921a4fdcb7becaab3b85ab7f5f3c858ecb28",
    "app/templates/data_tools/school_merger.html": "f398412623b9d6f3934d3344e05d11a061548ae899f9abe2b990e3fabd26fc22",
    "app/templates/data_tools/school_merger_plans.html": "359a7308b898437ad53c3413adedb9fbd531ae892228068ae641ea6c66349686"
}
EMBEDDED_FILES = {"app/services/school_merger_official_registry.py": "", "data/school_merger_official_registry.json": "", "app/routers/school_merger.py": "", "app/templates/data_tools/school_merger.html": "", "app/templates/data_tools/school_merger_plans.html": ""}


def sha256_file(path: Path) -> str:
    h = hashlib.sha256()
    with path.open('rb') as f:
        for chunk in iter(lambda: f.read(1024 * 1024), b''):
            h.update(chunk)
    return h.hexdigest()


def find_root() -> Path:
    candidates = [Path.cwd(), Path(r'C:\\PhoCap')]
    for c in candidates:
        if (c / 'app').is_dir() and (c / 'data').is_dir() and (c / 'app' / 'main.py').exists():
            return c.resolve()
    raise SystemExit('KHÔNG TÌM THẤY dự án. Hãy đặt file bộ cài trong C:\\PhoCap hoặc chạy: cd C:\\PhoCap')


def atomic_write(path: Path, data: bytes) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    tmp = path.with_name(path.name + '.tmp_sap_nhap_v2')
    tmp.write_bytes(data)
    os.replace(tmp, path)


def norm(value: str) -> str:
    text = str(value or '').strip().lower()
    text = unicodedata.normalize('NFD', text)
    text = ''.join(ch for ch in text if unicodedata.category(ch) != 'Mn')
    text = text.replace('đ', 'd')
    text = re.sub(r'[^a-z0-9]+', ' ', text)
    return ' '.join(text.split())


def bare_commune(value: str) -> str:
    return re.sub(r'^(xa|phuong|thi tran|thi xa|thanh pho)\s+', '', norm(value))


def school_key(value: str) -> str:
    return re.sub(r'^truong\s+', '', norm(value))


def verify_cua_lo(root: Path, registry: dict) -> list[str]:
    lines = []
    plans = [p for p in registry.get('plans', []) if p.get('commune_excel') == 'Cửa Lò' and 'TH' in (p.get('level_codes') or []) and 'THCS' not in (p.get('level_codes') or [])]
    lines.append(f'Cửa Lò - Tiểu học: {len(plans)} nhóm')
    expected = [
        ('Giữ nguyên', ['Tiểu học Nghi Hương']),
        ('Tiểu học Nghi Hải', ['Tiểu học Nghi Hải', 'Tiểu học Nghi Hoà']),
        ('Tiểu học Nghi Tân', ['Tiểu học Nghi Tân', 'Tiểu học Nghi Thuỷ']),
        ('Tiểu học Thu Thủy', ['Tiểu học Thu Thuỷ', 'Tiểu học Nghi Thu']),
    ]
    actual = [(str(p.get('plan_text') or ''), [str(m.get('school_name') or '') for m in p.get('members') or []]) for p in plans]
    if actual != expected:
        raise RuntimeError('Kiểm chứng Cửa Lò - Tiểu học KHÔNG ĐÚNG với file Excel đã chuẩn hóa: ' + repr(actual))

    db = root / 'data' / 'phocap.db'
    if not db.exists():
        raise RuntimeError('Không tìm thấy data\\phocap.db để đối chiếu Cửa Lò.')
    con = sqlite3.connect(str(db))
    con.row_factory = sqlite3.Row
    try:
        communes = [dict(r) for r in con.execute('SELECT id,code,name,is_active FROM communes').fetchall()]
        hits = [c for c in communes if bare_commune(c.get('name')) == bare_commune('Cửa Lò')]
        if len(hits) != 1:
            raise RuntimeError(f'Không khớp duy nhất địa bàn Cửa Lò trong DB: {[(x.get("id"),x.get("name")) for x in hits]}')
        cid = int(hits[0]['id'])
        schools = [dict(r) for r in con.execute('SELECT id,code,name,is_active FROM schools WHERE commune_id=?', (cid,)).fetchall()]
        for p in plans:
            for m in p.get('members') or []:
                wanted = school_key(m.get('school_name'))
                shits = [s for s in schools if school_key(s.get('name')) == wanted]
                if len(shits) != 1:
                    raise RuntimeError(f'Không khớp duy nhất trường {m.get("school_name")} tại Cửa Lò: {[(x.get("id"),x.get("name")) for x in shits]}')
        lines.append('Đối chiếu DB Cửa Lò: 7/7 trường Tiểu học khớp duy nhất.')
    finally:
        con.close()
    return lines


def main() -> None:
    root = find_root()
    print('=' * 88)
    print('BÀI SÁP NHẬP V2 - CHUẨN HÓA PHƯƠNG ÁN CHÍNH THỨC')
    print('Dự án:', root)
    print('Cam kết: KHÔNG ghi vào phocap.db; THỰC HIỆN SÁP NHẬP tiếp tục bị khóa.')
    print('=' * 88)

    # Kiểm tra phiên bản nguồn. Cho phép chạy lại nếu tệp đã đúng V2.
    mismatches = []
    for rel, expected_hash in EXPECTED_CURRENT.items():
        p = root / rel
        if not p.exists():
            mismatches.append(f'Thiếu tệp: {rel}')
            continue
        actual = sha256_file(p)
        if actual not in {expected_hash, NEW_HASHES.get(rel)}:
            mismatches.append(f'{rel} đã khác bản ZIP đã gửi (SHA256={actual})')
    if mismatches:
        print('\nDỪNG AN TOÀN: mã nguồn hiện tại khác bản PhoCap_SapNhap_V2.zip đã gửi cho ChatGPT.')
        for x in mismatches:
            print(' -', x)
        print('Không có tệp nào bị thay đổi.')
        raise SystemExit(2)

    db_path = root / 'data' / 'phocap.db'
    db_hash_before = sha256_file(db_path) if db_path.exists() else ''

    stamp = datetime.now().strftime('%Y%m%d_%H%M%S')
    backup_dir = root / 'backups' / f'backup_truoc_bai_sap_nhap_v2_{stamp}'
    backup_dir.mkdir(parents=True, exist_ok=False)

    # Backup toàn bộ tệp bị thay + sổ executable cũ để truy vết. Không copy DB vì bài này không ghi DB.
    backup_targets = list(EXPECTED_CURRENT.keys()) + [
        'app/services/school_merger_official_registry.py',
        'data/school_merger_official_registry.json',
        'data/school_merger_approved_plans.json',
    ]
    for rel in backup_targets:
        src = root / rel
        if src.exists():
            dst = backup_dir / rel
            dst.parent.mkdir(parents=True, exist_ok=True)
            shutil.copy2(src, dst)

    written = []
    for rel, b64 in EMBEDDED_FILES.items():
        data = base64.b64decode(b64.encode('ascii'))
        if hashlib.sha256(data).hexdigest() != NEW_HASHES[rel]:
            raise RuntimeError('Payload bộ cài bị lỗi SHA256: ' + rel)
        atomic_write(root / rel, data)
        written.append(rel)

    # Kiểm tra cú pháp Python.
    py_compile.compile(str(root / 'app/services/school_merger_official_registry.py'), doraise=True)
    py_compile.compile(str(root / 'app/routers/school_merger.py'), doraise=True)

    registry = json.loads((root / 'data/school_merger_official_registry.json').read_text(encoding='utf-8'))
    if int(registry.get('group_count') or 0) != 711 or len(registry.get('plans') or []) != 711:
        raise RuntimeError('Sổ phương án V2 không đủ 711 nhóm.')
    if registry.get('execution_enabled') is not False:
        raise RuntimeError('Cờ execution_enabled phải là False.')

    verify_lines = verify_cua_lo(root, registry)

    # Chứng minh database không thay đổi từng byte.
    db_hash_after = sha256_file(db_path) if db_path.exists() else ''
    if db_hash_before != db_hash_after:
        raise RuntimeError('CẢNH BÁO: SHA256 phocap.db đã thay đổi ngoài dự kiến. Hãy dừng hệ thống và dùng backup.')

    report = [
        'BÀI SÁP NHẬP V2 - CÀI ĐẶT THÀNH CÔNG',
        f'Thời gian: {datetime.now().isoformat(timespec="seconds")}',
        f'Dự án: {root}',
        f'Backup mã nguồn: {backup_dir}',
        '',
        'TỆP ĐÃ CÀI:',
        *[f' - {x}' for x in written],
        '',
        'KIỂM TRA:',
        ' - Sổ phương án chính thức: 711 nhóm.',
        ' - THỰC HIỆN SÁP NHẬP: KHÓA ở giao diện + backend.',
        ' - Database: KHÔNG thay đổi (SHA256 trước/sau giống nhau).',
        *[f' - {x}' for x in verify_lines],
        '',
        'CỬA LÒ - TIỂU HỌC CHUẨN:',
        ' 1) Tiểu học Nghi Hương -> Giữ nguyên.',
        ' 2) Tiểu học Nghi Hoà -> Tiểu học Nghi Hải.',
        ' 3) Tiểu học Nghi Thuỷ -> Tiểu học Nghi Tân.',
        ' 4) Tiểu học Nghi Thu -> Tiểu học Thu Thuỷ.',
    ]
    report_path = root / f'bao_cao_cai_sap_nhap_v2_{stamp}.txt'
    report_path.write_text('\n'.join(report) + '\n', encoding='utf-8')

    print('\n'.join(report))
    print('\nBƯỚC TIẾP THEO: khởi động lại Uvicorn, đăng nhập Sở/Quản trị, mở Sáp nhập trường,')
    print('chọn Năm học 2026-2027 -> Cửa Lò -> Tiểu học. Phải thấy đúng 4 nhóm trên.')


if __name__ == '__main__':
    try:
        main()
    except Exception as exc:
        print('\nCÀI ĐẶT KHÔNG THÀNH CÔNG:', exc)
        print('Nếu đã có thư mục backup_truoc_bai_sap_nhap_v2_..., giữ nguyên để khôi phục.')
        raise
